/**
 * Employment status (2026-10-23 — the user, circling the roster's EMPLOYMENT chip: "for the employment status, i want
 * go with permenant, part time and probation status follow by the hire date start. then if the probation is almost
 * end, then it will notification hr acknowledge for further action"): Probation, Permanent or Part time. Not the pay
 * basis — that is `employment_type` (Salaried, Fully commission based, Variable pay; lib/person-record.ts).
 *
 * A probation is a period counted from the hire date (mig 20261024214500: `probation_months`, and `probation_end`
 * generated by the database the same way `probationEnd` works it out here). HR is reminded before it ends — HR view's
 * bell — acknowledges, then confirms them as permanent, extends it, or ends their employment.
 * The people on the roster before that day carry no status ("Not set") until HR sets one (the user's answer).
 *
 * Contract (2026-10-24 — LI SEAN asked on IT-0006 for the Revenue team's contract status; the user: "can add with one
 * is Contract, then need pick time period as well, 6 month, 12 month, 18, 24, until 36"): a period counted from the
 * hire date the same way (mig 20261025013000: `contract_months`, `contract_end` generated).
 *
 * Either one's end — a TERM's — is reminded twice: 30 days before, then 15 (REMINDER_DAYS).
 *
 * Pure, so the roster, the person's window and page, the bell and both forms read one set of rules.
 */
import dayjs from 'dayjs'
import type { ChipTone } from '@/components/hrv/kit'
import { officeDay } from '@/lib/office-time'

export type EmploymentStatus = 'probation' | 'contract' | 'permanent' | 'part_time'

/** In the order the forms offer them — a new hire is most often on probation; a contract is the other with an end. */
export const EMPLOYMENT_STATUSES: readonly EmploymentStatus[] = ['probation', 'contract', 'permanent', 'part_time']

export const EMPLOYMENT_STATUS_LABEL: Readonly<Record<EmploymentStatus, string>> = {
  probation: 'Probation',
  contract: 'Contract',
  permanent: 'Permanent',
  part_time: 'Part time',
}

/** The four as a sentence says them — a refusal, a chip's hint. */
const STATUS_WORDS = 'Probation, Contract, Permanent or Part time'

/** A record filed before employment status existed, until HR sets it. */
export const NOT_SET = 'Not set'

/** The periods Add Staff offers; Extend adds to one. */
export const PROBATION_MONTH_CHOICES = [1, 2, 3, 4, 5, 6] as const
export const DEFAULT_PROBATION_MONTHS = 3
export const EXTEND_MONTH_CHOICES = [1, 2, 3] as const
/** The database's ceiling (hr_staff_costs_probation_months_check), extensions included. */
export const MAX_PROBATION_MONTHS = 24

/** A contract's periods (the user, 2026-10-24: "6 month, 12 month, 18, 24, until 36"). */
export const CONTRACT_MONTH_CHOICES = [6, 12, 18, 24, 30, 36] as const
export const DEFAULT_CONTRACT_MONTHS = 12
/** The database's ceiling (hr_staff_costs_contract_months_check). */
export const MAX_CONTRACT_MONTHS = 36

/**
 * HR is reminded twice before a probation or a contract ends: 30 days before, then 15 (the user, 2026-10-24: "need 30
 * days and 15 days before remind, 2 reminder, then for probation need same as well" — a probation was told once, 14
 * days before and then 15, a contract never). Each waits for Acknowledge, and the first's never answers the second.
 * notify_term_ends (mig 20261025046500) tells the phones on the same two days.
 */
export const REMINDER_DAYS = [30, 15] as const
export type Reminder = (typeof REMINDER_DAYS)[number]
/** From the first reminder on, the bell, the HR app and the roster's chip count the days. */
export const NOTICE_DAYS: Reminder = REMINDER_DAYS[0]
/** A form's hint under a term's end. */
export const REMINDER_HINT = `HR is reminded ${REMINDER_DAYS.join(' and ')} days before.`

export function employmentStatusOf(v: unknown): EmploymentStatus | null {
  return typeof v === 'string' && (EMPLOYMENT_STATUSES as readonly string[]).includes(v) ? (v as EmploymentStatus) : null
}

/** "1 month", "3 months". */
export function monthsLabel(n: number): string {
  return `${n} month${n === 1 ? '' : 's'}`
}

const YMD = /^(\d{4})-(\d{2})-(\d{2})$/

function parts(ymd: string): [number, number, number] | null {
  const m = YMD.exec(ymd)
  return m ? [Number(m[1]), Number(m[2]), Number(m[3])] : null
}

const utcDay = (y: number, m0: number, d: number) => Date.UTC(y, m0, d)
const ymdOf = (ms: number) => new Date(ms).toISOString().slice(0, 10)

/**
 * A probation's last day: the hire date plus the months, less a day — 1 Oct + 3 months → 31 Dec. Months are added the
 * way Postgres adds them (the day kept, or the month's last when it has fewer: 31 Jan + 1 month → 28 Feb, so the last
 * day is 27 Feb), so this is the database's `probation_end` to the day. Null without a hire date or a period.
 */
export function probationEnd(hireDate: string | null | undefined, months: number | null | undefined): string | null {
  const p = hireDate ? parts(hireDate) : null
  if (!p || !months || !Number.isInteger(months) || months < 1) return null
  const [y, m, d] = p
  const total = m - 1 + months
  const ty = y + Math.floor(total / 12)
  const tm = total % 12
  const last = new Date(utcDay(ty, tm + 1, 0)).getUTCDate()
  return ymdOf(utcDay(ty, tm, Math.min(d, last)) - 86_400_000)
}

/** A contract's last day, counted the same way — the database's `contract_end` (mig 20261025013000) to the day. */
export function contractEnd(hireDate: string | null | undefined, months: number | null | undefined): string | null {
  return probationEnd(hireDate, months)
}

/** Whole days from `from` to `to` (both YYYY-MM-DD) — positive when `to` is later. */
export function daysFrom(from: string, to: string): number {
  const a = parts(from)
  const b = parts(to)
  if (!a || !b) return 0
  return Math.round((utcDay(b[0], b[1] - 1, b[2]) - utcDay(a[0], a[1] - 1, a[2])) / 86_400_000)
}

/**
 * The reminder standing today for a term ending on `endsOn`: the first from 30 days before, the second from 15 days
 * before — and after the end, while the term is still open — or none before the first.
 */
export function reminderOf(endsOn: string | null | undefined, today: string): Reminder | null {
  if (!endsOn) return null
  const left = daysFrom(today, endsOn)
  return left <= REMINDER_DAYS[1] ? REMINDER_DAYS[1] : left <= REMINDER_DAYS[0] ? REMINDER_DAYS[0] : null
}

/** HR is being told: the term ends within NOTICE_DAYS of today — or has ended and is still open. */
export function reminderDue(endsOn: string | null | undefined, today: string): boolean {
  return reminderOf(endsOn, today) !== null
}

/** A term's acknowledgement as the database keeps it: for which end, when — and by whom. */
export interface TermAck {
  ackEnd: string | null
  ackAt: string | null
  ackName?: string | null
}

/**
 * The reminder an acknowledgement answered, by the office's day it was given on: the second when 15 days or fewer
 * were left (or the end had passed), the first when more. Null when it was given for another end — the term was
 * extended or renewed since — or never given.
 */
export function answeredReminder(endsOn: string | null | undefined, ack: TermAck): Reminder | null {
  if (!endsOn || !ack.ackEnd || ack.ackEnd !== endsOn || !ack.ackAt) return null
  return daysFrom(officeDay(ack.ackAt).format('YYYY-MM-DD'), endsOn) <= REMINDER_DAYS[1] ? REMINDER_DAYS[1] : REMINDER_DAYS[0]
}

/** Acknowledged for the reminder standing today — the first reminder's acknowledgement does not answer the second. */
export function reminderAcknowledged(endsOn: string | null | undefined, ack: TermAck, today: string): boolean {
  const answered = answeredReminder(endsOn, ack)
  if (answered === null) return false
  const standing = reminderOf(endsOn, today)
  return standing === null || answered <= standing
}

/**
 * What the acknowledgement says beside the term today: "Acknowledged" while it answers the reminder standing, "30-day
 * reminder acknowledged" once the second stands over the first's — or nothing.
 */
export function ackWords(endsOn: string | null | undefined, ack: TermAck, today: string): string | null {
  if (reminderAcknowledged(endsOn, ack, today)) return 'Acknowledged'
  return answeredReminder(endsOn, ack) === REMINDER_DAYS[0] ? `${REMINDER_DAYS[0]}-day reminder acknowledged` : null
}

/** When it ends, against today: "in 9 days", "tomorrow", "today", "yesterday", "3 days ago". */
export function whenLabel(endsOn: string, today: string): string {
  const n = daysFrom(today, endsOn)
  if (n === 0) return 'today'
  if (n === 1) return 'tomorrow'
  if (n === -1) return 'yesterday'
  return n > 0 ? `in ${n} days` : `${-n} days ago`
}

/** "31 Dec 2026" — a date column as the roster writes one. */
export function dayLabel(ymd: string): string {
  return dayjs(ymd).format('D MMM YYYY')
}

/** A term's end: "Ends 31 Dec 2026 · in 9 days" / "Ended 31 Dec 2026 · 3 days ago" — `lower` for inside a sentence. */
export function termEndLine(endsOn: string, today: string, lower = false): string {
  const verb = daysFrom(today, endsOn) < 0 ? 'Ended' : 'Ends'
  return `${lower ? verb.toLowerCase() : verb} ${dayLabel(endsOn)} · ${whenLabel(endsOn, today)}`
}

/** Where somebody's employment stands, as a chip says it — for the active (an inactive one keeps its own chip). */
export interface StatusChip {
  label: string
  tone: ChipTone
  title?: string
}

export interface StatusFacts {
  /** `undefined`: this reader is not shown it (the directory's rows) — the chip reads Active, as it always did. */
  status: EmploymentStatus | null | undefined
  probationEnd?: string | null
  /** A contract's last day (2026-10-24) — the database's `contract_end`. */
  contractEnd?: string | null
  /** The acknowledgement of the reminder for the term they are on — the probation's or the contract's. */
  ack?: TermAck | null
}

/**
 * The chip for an active person: Permanent (green), Part time (blue), Contract (peach), Probation (amber) — a term's
 * end in the hint, and from its first reminder on how near it is ("Probation · 9d left", "Contract · ends today",
 * "· ended") — or Not set.
 */
export function statusChip(f: StatusFacts, today: string): StatusChip {
  if (f.status === undefined) return { label: 'Active', tone: 'ledger' }
  if (f.status === null) return { label: NOT_SET, tone: 'plain', title: `Employment status not set — ${STATUS_WORDS}, on their page` }
  if (f.status === 'permanent') return { label: EMPLOYMENT_STATUS_LABEL.permanent, tone: 'ledger' }
  if (f.status === 'part_time') return { label: EMPLOYMENT_STATUS_LABEL.part_time, tone: 'info' }
  const label = EMPLOYMENT_STATUS_LABEL[f.status]
  const tone: ChipTone = f.status === 'contract' ? 'runOn' : 'alert'
  const endsOn = (f.status === 'contract' ? f.contractEnd : f.probationEnd) ?? null
  if (!endsOn) return { label, tone, title: `${label} — its end is counted from the hire date, which is missing` }
  const words = f.ack ? ackWords(endsOn, f.ack, today) : null
  const title = [`${label} ${termEndLine(endsOn, today, true)}`, words ? `${words}${f.ack?.ackName ? ` by ${f.ack.ackName}` : ''}` : null]
    .filter(Boolean)
    .join(' — ')
  if (!reminderDue(endsOn, today)) return { label, tone, title }
  const n = daysFrom(today, endsOn)
  return { label: `${label} · ${n > 0 ? `${n}d left` : n === 0 ? 'ends today' : 'ended'}`, tone, title }
}

/**
 * "Probation · 3 months · ends 31 Dec 2026", "Contract · 12 months · ends 30 Sep 2027", "Permanent", "Part time" — or
 * null when not set. `months` and `endsOn` are the period of whichever of the two it is.
 */
export function statusLine(status: EmploymentStatus | null, months: number | null, endsOn: string | null): string | null {
  if (!status) return null
  if (status !== 'probation' && status !== 'contract') return EMPLOYMENT_STATUS_LABEL[status]
  return [EMPLOYMENT_STATUS_LABEL[status], months ? monthsLabel(months) : null, endsOn ? `ends ${dayLabel(endsOn)}` : null].filter(Boolean).join(' · ')
}

/** What a form sent for the status and the period, checked: the columns to write — the other status's period cleared. */
export interface StatusColumns {
  employment_status: EmploymentStatus
  probation_months: number | null
  contract_months: number | null
}

/** A period a form sent, a whole number of months within the database's ceiling — or null. */
function monthsOf(raw: string | number | null | undefined, max: number): number | null {
  const months = Number((raw ?? '').toString().trim())
  return Number.isInteger(months) && months >= 1 && months <= max ? months : null
}

/**
 * The status a form chose and, for a probation or a contract, its period — refused in words for the screen. Add Staff
 * and the transfer always send it; a person's page only when it changed.
 */
export function statusColumns(
  rawStatus: string | null | undefined,
  rawMonths: string | number | null | undefined,
  rawContractMonths: string | number | null | undefined,
): StatusColumns {
  const status = employmentStatusOf((rawStatus ?? '').toString().trim())
  if (!status) throw new Error(`Pick the employment status — ${STATUS_WORDS}.`)
  if (status === 'probation') {
    const months = monthsOf(rawMonths, MAX_PROBATION_MONTHS)
    if (months === null) throw new Error('Pick the probation period.')
    return { employment_status: status, probation_months: months, contract_months: null }
  }
  if (status === 'contract') {
    const months = monthsOf(rawContractMonths, MAX_CONTRACT_MONTHS)
    if (months === null) throw new Error('Pick the contract period.')
    return { employment_status: status, probation_months: null, contract_months: months }
  }
  return { employment_status: status, probation_months: null, contract_months: null }
}
